SELECT SUM(MBSPA.TRNSIT_USER_CNT) AS "TRNSIT_USER_CNT" -- 환승수 ,SUM(MBSPA.RIDE_USER_CNT) AS "RIDE_USER_CNT" -- 승객수 ,SUM(MBSPA.LNDI_USER_CNT) AS "LNDI_USER_CNT" -- 버스 사용자수 ,GBS.SIDO_CD FROM MRT_BUS_STTN_PASNG_ANAL MBSPA INNER JOIN GGBIS_BUS_STATION GBS ON MBSPA.BSTP_ID = GBS.STATION_ID -- 승차정류장,하차정류장 where 1=1
AND TO_CHAR(TO_TIMESTAMP(MBSPA.ETL_DT, 'YYYYMMDDHH24MISS'), 'YYYY') = #{searchYear}
AND TO_CHAR(TO_TIMESTAMP(MBSPA.ETL_DT, 'YYYYMMDDHH24MISS'), 'D') BETWEEN '2' AND '6'
AND TO_CHAR(TO_TIMESTAMP(MBSPA.ETL_DT, 'YYYYMMDDHH24MISS'), 'D') = '1' OR TO_CHAR(MSCL.ANLS_DT::DATE, 'D') = '7'
AND TO_CHAR(TO_TIMESTAMP(MBSPA.ETL_DT, 'YYYYMMDDHH24MISS'), 'YYYY-MM-DD') BETWEEN #{startDate} AND #{endDate}
AND TO_CHAR(TO_TIMESTAMP(MBSPA.ETL_DT, 'YYYYMMDDHH24MISS'), 'HH24') BETWEEN '06' AND '10'
AND TO_CHAR(TO_TIMESTAMP(MBSPA.ETL_DT, 'YYYYMMDDHH24MISS'), 'HH24') BETWEEN '17' AND '20'
AND TO_CHAR(TO_TIMESTAMP(MBSPA.ETL_DT, 'YYYYMMDDHH24MISS'), 'HH24') BETWEEN #{startTime} AND #{endTime}
AND GBS.SIDO_CD LIKE CONCAT(#{sigunCdId},'%')
GROUP BY GBS.SIDO_CD
